    text: "W 1953 roku Węgry rozbiły Anglię na Wembley 6:3 — gospodarze po raz pierwszy przegrali u siebie z drużyną spoza Wysp Brytyjskich. Mecz zmusił Anglików do przemyślenia całej taktyki.",
