    id: "ma12",
    text: "Finał mistrzostw świata 2010 rozstrzygnął się dopiero w 116. minucie, po golu Andrésa Iniesty. Był to najbardziej faulowany finał w historii — sędzia pokazał czternaście żółtych kartek.",
